cards.solution:
const siswa = [
  { nama: "Budi", nilai: 88 },
  { nama: "Sari", nilai: 95 },
  { nama: "Andi", nilai: 88 },
  { nama: "Rina", nilai: 72 },
];
const peringkat = siswa.toSorted((a, b) => b.nilai - a.nilai || a.nama.localeCompare(b.nama));
peringkat.forEach((s, i) => console.log(`${i + 1}. ${s.nama} (${s.nilai})`));
